@page "/dashboard"
@rendermode InteractiveServer
@using sv_61a4c906f82544d89d21ef0ec54826e3.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h2>Warehouse Dashboard</h2>

<div class="card mt-3">
    <div class="card-header">
        <strong>@CurrentWarehouseName</strong> — Inventory Status
    </div>
    <div class="card-body">
        <div class="d-flex align-items-center gap-3">
            <h4 class="mb-0">Low-Stock Alerts:</h4>
            <AlertBadge />
        </div>
        <p class="text-muted mt-2 mb-0">
            Polling every 10 seconds. Data refreshes automatically when warehouse changes.
        </p>
    </div>
</div>

<div class="card mt-3">
    <div class="card-header">Activity Log</div>
    <div class="card-body">
        <ul class="list-group list-group-flush">
            @foreach (var entry in _log.TakeLast(10).Reverse())
            {
                <li class="list-group-item py-1 small">@entry</li>
            }
        </ul>
    </div>
</div>

@code {
    private readonly List<string> _log = new();

    private string CurrentWarehouseName =>
        WarehouseState.GetWarehouses()
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        // Subscribe to polling — starts the 10s timer
        AlertService.Subscribe();
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(() =>
        {
            _log.Add($"[{DateTime.Now:HH:mm:ss}] Alert count updated: {AlertService.LastLowStockCount} " +
                     $"for {WarehouseState.CurrentWarehouseId}");
            StateHasChanged();
        });
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(() =>
        {
            _log.Add($"[{DateTime.Now:HH:mm:ss}] Warehouse switched to: {CurrentWarehouseName}");
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        // Unsubscribe stops polling when no subscribers remain
        AlertService.Unsubscribe();
    }
}

